package agentguide

func workTools() []ToolEntry {
	var entries []ToolEntry
	field := func(name, typ, meaning string, required bool) Field { return Field{name, typ, required, meaning} }
	product := field("product_id", "string", "Product scope; omission means all visible products", false)
	feature := field("feature_id", "string", "Visible feature that owns the question or proposal", true)
	action := func(name, purpose, when, output, code, handling, example, authority string, fields ...Field) {
		fields = append([]Field{field("action", "string", "Exact execute action name", true), field("data", "object", "Action-specific payload", true)}, fields...)
		entries = append(entries, ToolEntry{Name: name, Kind: "execute_action", Area: "owner_work", Purpose: purpose, When: when, Inputs: fields, Output: output, Errors: []ErrorInfo{{code, handling}}, Example: example, Related: []string{"list_questions", "get_dependency_graph", "next_work"}, Authority: authority})
	}
	action("ask_question", "Store an owner question with its context and recommendation.", "Before pausing for owner input; reference visible records in the same Product.", "Open question memory; a blocking question can pause the caller's live lease.", "VALIDATION", "Supply a recommendation for conflicts and decisions.", `{"action":"ask_question","feature_id":"FEATURE","integration_id":"INTEGRATION","data":{"title":"Keep v1?","body":"Two consumers still use v1.","kind":"decision","options":[{"id":"keep","label":"Keep v1","consequence":"No client migration"}],"recommendation":"keep","context_refs":["FEATURE"],"blocking":true}}`, "The server resolves the addressee and asker. This does not grant a lease.", feature, field("integration_id", "string", "Optional Integration scope", false), field("kind", "string", "question, conflict, or decision", true), field("options", "array[object]", "Stable option IDs, labels and consequences", false), field("context_refs", "array[string]", "Same-Product feature, integration, memory, or finding IDs", false))
	action("answer_questions", "Record a batch of owner-approved, context-validated answers atomically.", "Fetch questions from RCP, validate every answer, and object before relaying a contradiction.", "Answered question records and durable decision memories; blockers resolve and wake when applicable.", "ANSWER_NEEDS_CLARIFICATION", "Explain the conflict or ambiguity to the owner; override only after they insist.", `{"action":"answer_questions","data":{"answers":[{"question_id":"QUESTION","text":"Keep v1 until clients migrate.","option_id":"keep","validation":{"verdict":"consistent","note":"Both clients still depend on v1."}}]}}`, "Only the addressee or their agent may answer. The verdict is caller-supplied, not a server fact check.", field("answers", "array[object]", "Question ID, text, optional option, validation verdict and note, optional override", true))
	action("withdraw_question", "Withdraw an open question and retain the reason.", "When the question no longer needs an answer.", "Withdrawn question memory and resolution of any linked blocker.", "NOT_FOUND", "Use the exact visible question ID from RCP.", `{"action":"withdraw_question","data":{"question_id":"QUESTION","reason":"The client migration finished."}}`, "Only the asker, addressee, or their agents may withdraw.", field("question_id", "string", "Open question ID", true), field("reason", "string", "Reason the answer is no longer needed", true))
	action("set_idea_promotion", "Set the Product's agent approval policy.", "When the Product owner explicitly delegates or revokes routine approvals.", "Updated Product policy.", "FORBIDDEN", "Only the Product owner as a human may set this policy.", `{"action":"set_idea_promotion","product_id":"PRODUCT","data":{"idea_promotion":"ask_owner"}}`, "Default ask_owner; agent_allowed does not grant Product access or release rights.", field("product_id", "string", "Owned Product", true), field("idea_promotion", "string", "ask_owner or agent_allowed", true))
	action("request_idea_promotion", "Ask the owner to promote an idea.", "When an idea is actionable and agent approval policy requires a decision.", "Open approve/reject decision; approval atomically moves the idea to ready_for_execution.", "VALIDATION", "Use a feature that is still an idea and does not have an open promotion request.", `{"action":"request_idea_promotion","feature_id":"FEATURE","data":{"rationale":"Acceptance criteria and prerequisites are known."}}`, "Asks for approval; it does not start execution.", feature, field("rationale", "string", "Why the idea is ready now", true))
	action("propose_dependency", "Propose a requires or relates edge between visible features.", "When planning work with the owner; requires means the target must complete first.", "New proposed edge, or accepted edge for an eligible human requesting direct acceptance.", "DEPENDENCY_CYCLE", "Remove the proposed cycle before accepting a requires edge.", `{"action":"propose_dependency","data":{"from_feature_id":"FEATURE","to_feature_id":"PREREQUISITE","type":"requires","rationale":"Needs the schema change first."}}`, "Requires write access to both Products; agents propose by default.", field("from_feature_id", "string", "Dependent feature", true), field("to_feature_id", "string", "Prerequisite or related feature", true), field("type", "string", "requires or relates", true), field("rationale", "string", "Why this relationship exists", true), field("accept", "boolean", "Human-only direct acceptance", false))
	action("decide_dependency", "Accept or reject a proposed dependency.", "After reviewing the exact proposed edge and its effect on execution.", "Decided edge with attribution and timestamp.", "OWNER_APPROVAL_REQUIRED", "Ask the owner or have them explicitly enable agent_allowed.", `{"action":"decide_dependency","data":{"dependency_id":"EDGE","decision":"accept"}}`, "Requires write access to both Products; agent acceptance needs policy or an exact approving decision.", field("dependency_id", "string", "Proposed edge", true), field("decision", "string", "accept or reject", true), field("approval_question_id", "string", "Answered approval for this edge", false))
	action("request_dependency_decision", "Ask the Product owner to approve an exact action on a proposed edge.", "When the agent cannot decide under Product policy.", "Open decision question bound to the edge, action, and attempt.", "VALIDATION", "Use an open proposal the owner can review in the dependency graph.", `{"action":"request_dependency_decision","data":{"dependency_id":"EDGE","decision":"accept"}}`, "Only creates a question; the Product owner must decide.", field("dependency_id", "string", "Proposed edge", true), field("decision", "string", "Action to approve: accept (default) or reject", false))
	action("register_user_orchestrator", "Register the current user's harness for work-available wakes.", "When starting a supervisor-backed personal work queue.", "User and optional Product-scoped registration and current generation.", "VALIDATION", "Specify a supported harness kind and session reference or tmux target.", `{"action":"register_user_orchestrator","product_id":"PRODUCT","data":{"harness":{"kind":"codex","tmux_target":"rcp:1.0"}}}`, "Registers the caller only. A wake is not a claim or execution authority.", product, field("harness", "object", "Kind plus session_ref or tmux_target", true))
	action("unregister_user_orchestrator", "Remove the current user's work wake registration.", "When stopping the registered orchestrator.", "Reports whether a registration was removed; queued wakes are retired.", "FORBIDDEN", "Use the registering human identity or its agent and the same scope.", `{"action":"unregister_user_orchestrator","product_id":"PRODUCT","data":{}}`, "Cannot unregister another user or modify their execution lease.", product)
	query := func(name, route, purpose, when, output, example, httpExample string, fields ...Field) {
		entry := ToolEntry{Name: name, Kind: "mcp_tool", Area: "owner_work", Purpose: purpose, When: when, Output: output, Inputs: fields, Errors: []ErrorInfo{{"NOT_FOUND", "Check that the requested scope is visible for " + name + "."}}, Example: example, Related: []string{"list_questions", "next_work"}, Authority: "Read-only; does not grant access or change ownership."}
		entries = append(entries, entry)
		entry.Name, entry.Kind, entry.Example = route, "http_route", httpExample
		entries = append(entries, entry)
	}
	query("list_questions", "GET /api/questions", "List visible questions addressed to the selected human.", "Fetch the current batch from RCP before consulting the owner.", "Question titles, bodies, options, resolved context titles and pagination cursor.", `{"status":"open","addressed_to":"me"}`, `GET /api/questions?addressed_to=me`, product, field("addressed_to", "string", "Human ID; defaults to me", false), field("status", "string", "open, answered or withdrawn", false), field("feature_id", "string", "Optional visible feature filter", false), field("limit", "integer", "Page size, max 100", false), field("cursor", "string", "Continuation from previous page", false))
	query("get_question", "GET /api/questions/{id}", "Read one visible question and its answer.", "Verify live context, options and scope before relaying an answer.", "Full question with resolved context titles and any recorded answer.", `{"question_id":"QUESTION"}`, `GET /api/questions/QUESTION`, field("question_id", "string", "Exact question ID (id in HTTP path)", true))
	query("get_dependency_graph", "GET /api/products/{id}/dependency-graph", "Read visible feature dependency edges and readiness.", "Before planning work or reviewing a proposed dependency.", "Nodes, waiting_on prerequisites and accepted or optionally proposed edges.", `{"product_id":"PRODUCT","include_proposed":true}`, `GET /api/products/PRODUCT/dependency-graph?include_proposed=true`, field("product_id", "string", "Visible Product (id in HTTP path)", true), field("include_proposed", "boolean", "Include proposals in addition to accepted edges", false))
	query("next_work", "GET /api/next-work", "Read the caller's ordered execution and planning queue.", "After a work_available wake or when looking for eligible work.", "Eligible items, including assignee-only resume items with a fence and next action, and up to 20 blocked items with redacted reasons.", `{"limit":10}`, `GET /api/next-work?limit=10`, product, field("limit", "integer", "Eligible item limit, max 100", false))
	query("status_overview", "GET /api/status-overview", "Read per-Product owner-work counts and short lists.", "For a laptop overview of questions, ideas, execution and recent completions.", "Visible Products and bounded lists with complete counts.", `{}`, `GET /api/status-overview`, product)
	return entries
}
